const focusSeries={84:[6.85,7.25,8.53,8.03,7.75,8.35,7.75,8.93,8.08,8.80,7.42],110:[9.60,9.55,8.00,9.85,9.00]};
const focusLabels={84:['25.09','25.10','25.11','25.12','26.01','26.02','26.03','26.04','26.05','26.06','26.07'],110:['25.08','25.11','26.01','26.04','26.05']};
const nearby=[
 {name:'수성푸르지오리버센트',date:'26.07.11 · 84㎡ · 11층',price:7.20,lat:35.8476,lon:128.6103,label:'분석 대상'},
 {name:'수성효성해링턴플레이스',date:'26.10.02 · 84㎡ · 16층',price:6.30,lat:35.8521,lon:128.6082,label:'북측 비교'},
 {name:'수성골드클래스더센텀',date:'26.08.21 · 84㎡ · 3층',price:5.72,lat:35.8441,lon:128.6129,label:'남측 비교'},
 {name:'수성데시앙리버뷰',date:'최근 1년 최고가 기준',price:11.50,lat:35.8490,lon:128.6155,label:'대형 평형 포함'}
];
function drawFocus(area='84'){let a=focusSeries[area],labels=focusLabels[area],w=680,h=180,p=28,min=6,max=10.2,x=i=>p+i*(w-p*2)/(a.length-1||1),y=v=>h-p-(v-min)/(max-min)*(h-p*2),path=a.map((v,i)=>`${i?'L':'M'}${x(i)},${y(v)}`).join(' ');focusPriceChart.innerHTML=`<svg viewBox="0 0 ${w} ${h}" preserveAspectRatio="none">${[6,7,8,9,10].map(v=>`<line x1="${p}" y1="${y(v)}" x2="${w-p}" y2="${y(v)}" stroke="#e4e8e4"/><text x="1" y="${y(v)+3}" class="axis-label">${v}억</text>`).join('')}<path d="${path}" fill="none" stroke="#0d6b46" stroke-width="4"/>${a.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="#fff" stroke="#ef6d36" stroke-width="3"><title>${labels[i]} · ${v.toFixed(2)}억원</title></circle><text x="${x(i)}" y="175" text-anchor="middle" class="axis-label">${labels[i]}</text>`).join('')}</svg>`}
nearbyCompare.innerHTML=nearby.map((x,i)=>`<div class="compare-row" data-i="${i}"><div><b>${x.name}</b><small>${x.date}</small></div><div class="compare-bar"><i style="width:${x.price/11.5*100}%"></i></div><strong>${x.price.toFixed(2)}억</strong></div>`).join('');
function focusMapUrl(lat,lon){let z=.012,b=[lon-z,lat-z,lon+z,lat+z].map(x=>x.toFixed(6)).join('%2C');return `https://www.openstreetmap.org/export/embed.html?bbox=${b}&layer=mapnik&marker=${lat}%2C${lon}`}
function setFocusPlace(i=0){let x=nearby[i];focusMap.src=focusMapUrl(x.lat,x.lon);focusMapTitle.textContent=x.name;focusMapLabel.textContent=x.label;focusMapLink.href=`https://www.openstreetmap.org/?mlat=${x.lat}&mlon=${x.lon}#map=16/${x.lat}/${x.lon}`;document.querySelectorAll('.focus-place').forEach((b,j)=>b.classList.toggle('active',j===i))}
focusMapPlaces.innerHTML=nearby.map((x,i)=>`<button class="focus-place" data-i="${i}">${x.name}<span>${x.price.toFixed(2)}억</span></button>`).join('');focusMapPlaces.onclick=e=>{let b=e.target.closest('button');if(b)setFocusPlace(+b.dataset.i)};nearbyCompare.onclick=e=>{let r=e.target.closest('.compare-row');if(r){setFocusPlace(+r.dataset.i);focusMap.scrollIntoView({behavior:'smooth',block:'center'})}};document.querySelector('.focus-switch').onclick=e=>{if(!e.target.matches('button'))return;document.querySelectorAll('.focus-switch button').forEach(b=>b.classList.remove('active'));e.target.classList.add('active');drawFocus(e.target.dataset.area)};drawFocus();setFocusPlace();
